// Normalize Incoming Email — Tooba support final reply logging v1
// Output: requestId, senderEmail, senderName, subject, cleanBody, conversationId, messageId.
// Invalid emails return [] to stop downstream nodes.

const item = $input.first().json;

function getEmailAddress(obj) {
  const ea = obj?.emailAddress || obj || {};
  return {
    name: String(ea.name || ea.displayName || '').trim(),
    address: String(ea.address || ea.email || ea.emailAddress || '').toLowerCase().trim(),
  };
}

function htmlToText(input) {
  if (!input) return '';
  return String(input)
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const messageId = item.id || item.messageId || null;
const internetMessageId = item.internetMessageId || null;
const conversationId = item.conversationId || null;
const subject = String(item.subject || '').trim();
const subjectNormalized = subject.toLowerCase();

if (!messageId) return [];
if (!conversationId) return [];
if (item.isDraft === true) return [];

// Process only original incoming Tooba Feedback.
// Do not process replies.
if (subjectNormalized !== 'tooba feedback') return [];

const rawBody = item.body?.content || item.bodyPreview || '';
let cleanBody = htmlToText(rawBody);

// Extract request id if present.
// Examples:
// "ID обращения: 12596"
// "ID: 12596"
const requestIdMatch =
  cleanBody.match(/ID\s*обращения\s*[:：]\s*(\d+)/i) ||
  cleanBody.match(/\bID\s*[:：]\s*(\d+)/i);

const requestId = requestIdMatch?.[1] || '';

// Real customer email can be in replyTo, ccRecipients, or body:
// "Отправлено от email@example.com"
const embeddedSenderMatch = cleanBody.match(/Отправлено от\s+([^\s<>]+@[^\s<>]+)/i);
const embeddedSenderEmail = embeddedSenderMatch?.[1]?.toLowerCase()?.trim() || '';

const explicitEmailMatch =
  cleanBody.match(/Email\s*[:：]\s*([^\s<>]+@[^\s<>]+)/i);

const explicitEmail = explicitEmailMatch?.[1]?.toLowerCase()?.trim() || '';

// Remove technical lines from text.
cleanBody = cleanBody
  .replace(/\n?\s*Отправлено от\s+[^\s<>]+@[^\s<>]+/i, '')
  .replace(/^\s*ID\s*обращения\s*[:：]\s*\d+\s*$/gim, '')
  .replace(/^\s*ID\s*[:：]\s*\d+\s*$/gim, '')
  .replace(/^\s*Email\s*[:：]\s*[^\s<>]+@[^\s<>]+\s*$/gim, '')
  .replace(/^\s*Сообщение\s*[:：]\s*/gim, '')
  .trim();

const from = getEmailAddress(item.from);
const sender = getEmailAddress(item.sender);

const replyTo = Array.isArray(item.replyTo) && item.replyTo.length
  ? getEmailAddress(item.replyTo[0])
  : { name: '', address: '' };

const ccCustomer = Array.isArray(item.ccRecipients)
  ? item.ccRecipients
      .map(getEmailAddress)
      .find(e =>
        e.address &&
        !e.address.includes('support@tooba.com') &&
        !e.address.includes('@tooba.com') &&
        !e.address.includes('@mx.tooba.com')
      )
  : null;

let customer =
  replyTo.address
    ? replyTo
    : ccCustomer?.address
      ? ccCustomer
      : explicitEmail
        ? { name: explicitEmail, address: explicitEmail }
        : embeddedSenderEmail
          ? { name: embeddedSenderEmail, address: embeddedSenderEmail }
          : from.address
            ? from
            : sender;

let senderEmail = customer.address || '';
let senderName = customer.name || senderEmail;

if (!senderEmail) return [];
if (senderEmail === 'unknown') return [];
if (senderEmail.includes('support@tooba.com')) return [];
if (senderEmail.includes('no-reply@mx.tooba.com')) return [];

if (!senderName || senderName.toLowerCase() === senderEmail.toLowerCase()) {
  senderName = senderEmail;
}

cleanBody = cleanBody
  .replace(/Outlook:\s*https?:\/\/\S+/gi, '')
  .trim();

if (!cleanBody || cleanBody.length < 3) return [];

return [{
  json: {
    requestId,
    senderEmail,
    senderName,
    subject,
    cleanBody,
    messageId,
    internetMessageId,
    conversationId,
    webLink: item.webLink || null,
    receivedDateTime: item.receivedDateTime || null
  }
}];

const email = $('📧 Normalize Incoming Email').first().json;
const slack = $('💬 Post Request to Slack').first().json;

const channelId = 'C0ATU9ZD2UF';
const threadTs = slack.ts;

if (!email.conversationId || !threadTs) {
  return [];
}

const sd = $getWorkflowStaticData('global');

if (!sd.conversationToSlackThread) {
  sd.conversationToSlackThread = {};
}

if (!sd.processedIncomingMessageIds) {
  sd.processedIncomingMessageIds = [];
}

// Store/overwrite by conversationId.
sd.conversationToSlackThread[email.conversationId] = {
  channelId,
  threadTs,
  requestId: email.requestId || '',
  senderEmail: email.senderEmail,
  subject: email.subject,
  originalMessageId: email.messageId,
  storedAt: new Date().toISOString()
};

// Keep lightweight incoming dedup list.
if (!sd.processedIncomingMessageIds.includes(email.messageId)) {
  sd.processedIncomingMessageIds.push(email.messageId);
  if (sd.processedIncomingMessageIds.length > 500) {
    sd.processedIncomingMessageIds = sd.processedIncomingMessageIds.slice(-500);
  }
}

return [{
  json: {
    ok: true,
    conversationId: email.conversationId,
    channelId,
    threadTs
  }
}];

// Normalize Sent Reply — take actual manager-sent Outlook reply.
// It must match a previously stored conversationId.

const item = $input.first().json;

function getEmailAddress(obj) {
  const ea = obj?.emailAddress || obj || {};
  return {
    name: String(ea.name || ea.displayName || '').trim(),
    address: String(ea.address || ea.email || ea.emailAddress || '').toLowerCase().trim(),
  };
}

function htmlToText(input) {
  if (!input) return '';
  return String(input)
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function stripQuotedHistory(text) {
  if (!text) return '';

  const markers = [
    /\n-{2,}\s*Original Message\s*-{2,}/i,
    /\nОт:\s.+/i,
    /\nFrom:\s.+/i,
    /\nOn .+ wrote:/i,
    /\n.*написал\(а\):/i,
    /\n________________________________\s*\n/i
  ];

  let cutIndex = -1;

  for (const marker of markers) {
    const match = marker.exec(text);
    if (match && (cutIndex === -1 || match.index < cutIndex)) {
      cutIndex = match.index;
    }
  }

  if (cutIndex >= 0) {
    return text.slice(0, cutIndex).trim();
  }

  return text.trim();
}

const messageId = item.id || item.messageId || null;
const conversationId = item.conversationId || null;
const subject = String(item.subject || '').trim();

if (!messageId) return [];
if (!conversationId) return [];
if (item.isDraft === true) return [];

const sd = $getWorkflowStaticData('global');

if (!sd.conversationToSlackThread || !sd.conversationToSlackThread[conversationId]) {
  return [];
}

if (!sd.processedSentMessageIds) {
  sd.processedSentMessageIds = [];
}

if (sd.processedSentMessageIds.includes(messageId)) {
  return [];
}

const from = getEmailAddress(item.from || item.sender);

const toRecipients = Array.isArray(item.toRecipients)
  ? item.toRecipients.map(getEmailAddress).filter(e => e.address)
  : [];

const rawBody = item.body?.content || item.bodyPreview || '';
let sentReplyText = stripQuotedHistory(htmlToText(rawBody));

sentReplyText = sentReplyText
  .replace(/^\s*Получите Outlook для .+$/gim, '')
  .trim();

if (!sentReplyText || sentReplyText.length < 2) return [];

const mapping = sd.conversationToSlackThread[conversationId];

// Mark sent as processed only before output to avoid duplicate Slack posts.
// This is acceptable for sent replies because Slack post is the only action.
sd.processedSentMessageIds.push(messageId);
if (sd.processedSentMessageIds.length > 500) {
  sd.processedSentMessageIds = sd.processedSentMessageIds.slice(-500);
}

return [{
  json: {
    messageId,
    conversationId,
    subject,
    fromEmail: from.address,
    fromName: from.name || from.address,
    toEmails: toRecipients.map(e => e.address).join(', '),
    sentReplyText,
    slackChannelId: mapping.channelId,
    slackThreadTs: mapping.threadTs,
    requestId: mapping.requestId || '',
    originalSenderEmail: mapping.senderEmail || '',
    sentDateTime: item.sentDateTime || null
  }
}];

const data = $input.first().json;

if (!data.slackChannelId || !data.slackThreadTs || !data.sentReplyText) {
  return [];
}

return [{
  json: data
}];

